def grouped_by_era(entries, era_order):
    """Groups a flat list of {..., 'era': ...} dicts into era-ordered
    buckets for template rendering. Eras with zero entries are dropped
    rather than shown empty."""
    by_era = {era: [] for era in era_order}
    for e in entries:
        by_era.setdefault(e["era"], []).append(e)
    return [(era, by_era[era]) for era in era_order if by_era.get(era)]
